prompt --application/shared_components/plugins/template_component/amc_next_pricing
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(240205236024068677)
,p_plugin_type=>'TEMPLATE COMPONENT'
,p_name=>'AMC_NEXT_PRICING'
,p_display_name=>'Next Pricing'
,p_supported_component_types=>'PARTIAL:REPORT'
,p_partial_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-NPricing amc-NPricing--#STYLE#{case HIGHLIGHT/}{when Y/} is-featured{endcase/}">',
'  <div class="amc-NPricing-card"{case STYLE/}{when spotlight/} data-amc-pointer="spot"{when holoPremium/} data-amc-pointer="holo"{when tilt3d/} data-amc-pointer="tilt"{otherwise/}{endcase/}>',
'    {case STYLE/}{when beamFeatured/}<span class="amc-NPricing-beam" aria-hidden="true"></span>{when spotlight/}<span class="amc-NPricing-spot" aria-hidden="true"></span>{when holoPremium/}<span class="amc-NPricing-foil" aria-hidden="true"></span>{when auroraDark/}<span class="amc-NPricing-aurora" aria-hidden="true"></span>{when tilt3d/}<span class="amc-NPricing-glare" aria-hidden="true"></span>{otherwise/}{endcase/}',
'    <div class="amc-NPricing-top">',
'      <div class="amc-NPricing-head">',
'        {if ?ICON/}<span class="amc-NPricing-icon" aria-hidden="true"><span class="fa #ICON#"></span></span>{endif/}',
'        <h3 class="amc-NPricing-plan">#PLAN#</h3>',
'        {if ?BADGE/}<span class="amc-NPricing-badge">#BADGE#</span>{endif/}',
'      </div>',
'      {if ?DESCRIPTION/}<p class="amc-NPricing-desc">#DESCRIPTION#</p>{endif/}',
'      {case STYLE/}{when flipAnnual/}<div class="amc-NPricing-flip" tabindex="0" role="group">',
'        <div class="amc-NPricing-flipInner">',
'          <div class="amc-NPricing-side amc-NPricing-side--month">',
'            <p class="amc-NPricing-price">{if ?CURRENCY/}<span class="amc-NPricing-currency">#CURRENCY#</span>{endif/}<span class="amc-NPricing-amount">#PRICE#</span>{if ?PERIOD/}<span class="amc-NPricing-period">#PERIOD#</span>{endif/}</p>',
'            {if ?ANNUAL_PRICE/}<span class="amc-NPricing-flipHint" aria-hidden="true"><span class="fa fa-refresh"></span>{if ?SAVINGS/}<span class="amc-NPricing-flipHintText">#SAVINGS#</span>{endif/}</span>{endif/}',
'          </div>',
'          {if ?ANNUAL_PRICE/}<div class="amc-NPricing-side amc-NPricing-side--year">',
'            <p class="amc-NPricing-price">{if ?CURRENCY/}<span class="amc-NPricing-currency">#CURRENCY#</span>{endif/}<span class="amc-NPricing-amount">#ANNUAL_PRICE#</span><span class="amc-NPricing-period">{if ?ANNUAL_PERIOD/}#ANNUAL_PERIOD#{else/}/ year{endif/}</span></p>',
'            {if ?SAVINGS/}<span class="amc-NPricing-save">#SAVINGS#</span>{endif/}',
'          </div>{endif/}',
'        </div>',
'      </div>{otherwise/}<p class="amc-NPricing-price">{if ?CURRENCY/}<span class="amc-NPricing-currency">#CURRENCY#</span>{endif/}<span class="amc-NPricing-amount">#PRICE#</span>{if ?PERIOD/}<span class="amc-NPricing-period">#PERIOD#</span>{endif/}</p>{endcase/}',
'    </div>',
'    <div class="amc-NPricing-body">',
'      {if ?FEATURES/}<div class="amc-NPricing-features">#FEATURES#</div>{endif/}',
'      {if ?CTA_LABEL/}<div class="amc-NPricing-action">{if ?CTA_URL/}<a class="t-Button{case HIGHLIGHT/}{when Y/} t-Button--hot{endcase/} amc-NPricing-cta" href="#CTA_URL#">{else/}<button class="t-Button{case HIGHLIGHT/}{when Y/} t-Button--hot{endcase/} amc-NPricing-cta" type="button">{endif/}<span class="t-Button-label">#CTA_LABEL#</span>{if ?CTA_URL/}</a>{else/}</button>{endif/}</div>{endif/}',
'    </div>',
'  </div>',
'</div>'))
,p_default_escape_mode=>'HTML'
,p_translate_this_template=>true
,p_api_version=>1
,p_report_body_template=>'<div class="amc-NPricings-frame"><ul class="amc-NPricings amc-NPricings--#STYLE#">#APEX$ROWS#</ul></div>'
,p_report_row_template=>'<li class="amc-NPricings-item{case HIGHLIGHT/}{when Y/} is-featured{endcase/}">#APEX$PARTIAL#</li>'
,p_css_file_urls=>'#PLUGIN_FILES#amc-next-pricing.css'
,p_javascript_file_urls=>'#PLUGIN_FILES#amc-next-pricing.js'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'Pick a Style, then map Plan, Price, Currency, Period, Description and Features (separated by |). CTA Label and CTA URL add a native Universal Theme button. Highlight = Y marks the recommended plan; Beam Featured, Holo Premium and Tilt 3D give it their strongest treatment. Flip Annual also uses Annual Price, Annual Period and Savings. Every style is complete without JavaScript; the runtime file only builds the feature lists and adds the pointer spotlight and tilt.'
,p_version_identifier=>'1.0.1'
,p_files_version=>2
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(341838487245419071)
,p_plugin_id=>wwv_flow_imp.id(240205236024068677)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'STYLE'
,p_prompt=>'Style'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'beamFeatured'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'The pricing design, grouped by direction. Motion - Beam Featured: the highlighted plan has a travelling border beam and a glow. Motion - Spotlight: a pointer spotlight lights the borders of all plan cards at once. Depth - Tilt 3D: plans tilt toward the pointer, the price floats on its own layer and the highlighted plan stands forward. Depth - Flip Annual: the price slab flips on hover or focus to show Annual Price and Savings. Bold - Neo Brutal: ink borders, hard shadows, sticker badge. Bold - Clay: soft pillowy plans with clay check bubbles. Bold - Holo Premium: the highlighted plan becomes a holographic foil card. Bold - Aurora Dark: night cards with an aurora glow and grain. Smart - Expand Features: compact plans show three features and open the full list on hover or focus. Smart - Comparison Adaptive: cards when the region is wide, aligned comparison rows when it is narrow. Under reduced motion every effect stops and the static design stays.'
);
